using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 – Discriminator property renamed.
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", so force the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 – id value format changed.
            // EF Core 8 wrote id as "Product|123"; EF Core 9 writes just "123".
            // Existing documents still carry the old format, so we keep it via
            // the (internal) IdValueGeneratorFactory that produces "EntityType|Key".
            entity.Property<string>("__id")
                .HasValueGeneratorFactory<
                    Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal.IdValueGeneratorFactory>();

            // BREAKING CHANGE 3 – HasIndex is not supported by the Cosmos provider
            // and now throws. Removed the previous HasIndex(p => p.Sku) call.
        });
    }
}

// Changed Id to string so EF Core 9 can round-trip the "Product|123" id values
// stored in existing documents.
class Product { public string Id { get; set; } public string Sku { get; set; } }

